class BytesIOCopy:
    """A ``BytesIO``-like stream backed by a real OS-level file, so it
    provides a valid ``fileno()``. This lets code under test pass
    ``sys.stdout``/``sys.stderr`` directly to APIs like
    :func:`subprocess.run` without raising ``io.UnsupportedOperation``.
    The written stream is also copied to another stream.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._file = tempfile.TemporaryFile()
        self.copy_to = copy_to

    def __getattr__(self, name: str) -> t.Any:
        return getattr(self._file, name)

    def flush(self) -> None:
        self._file.flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return self._file.write(b)

    def getvalue(self) -> bytes:
        pos = self._file.tell()
        self._file.seek(0)
        data = self._file.read()
        self._file.seek(pos)
        return data

